const item = $json;
const wh = $('Webhook').first().json;
const consulta = wh.consulta ?? wh.body?.consulta ?? item.consulta ?? item.body?.consulta ?? '';
const content = item?.choices?.[0]?.message?.content;

let resultado = null;
if (content) {
  const limpio = content.replace(/^```(?:json)?/m, '').replace(/```$/m, '').trim();
  try {
    resultado = JSON.parse(limpio);
  } catch (e) {
    resultado = { error: 'No se pudo parsear la respuesta del LLM: ' + e.message };
  }
}

const cap = (s, def) => (s ? String(s).charAt(0).toUpperCase() + String(s).slice(1) : (def ?? 'N/A'));

const categoria = cap(resultado?.categoria, 'Sin clasificar');
const prioridad = cap(resultado?.prioridad, 'Media');
const resumen = (resultado?.resumen || (resultado?.error ?? 'No disponible')).trim();
const fecha = new Date().toISOString();
const filenombre = 'consulta-' + new Date().toISOString().replace(/[:.]/g, '-') + '.md';

const markdown = `# Clasificacion de consulta\n\n- **Categoria:** ${categoria}\n- **Prioridad:** ${prioridad}\n- **Fecha:** ${fecha}\n\n## Consulta original\n\n> ${consulta || '(sin texto)'}\n\n## Resumen\n\n${resumen}\n`;

return { ...item, consulta, categoria, prioridad, resumen, filenombre, markdown };
